import{_ as a,c as e,o as n,ag as i}from"./chunks/framework.bCALENAD.js";const u=JSON.parse('{"title":"前端框架问题","description":"","frontmatter":{},"headers":[],"relativePath":"interview/8part/framework.md","filePath":"interview/8part/framework.md","lastUpdated":1786609894000}'),p={name:"interview/8part/framework.md"};function t(l,s,r,o,c,d){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="前端框架问题" tabindex="-1">前端框架问题 <a class="header-anchor" href="#前端框架问题" aria-label="Permalink to &quot;前端框架问题&quot;">​</a></h1><h2 id="vue-路由-query-vs-params" tabindex="-1">Vue 路由：<code>query</code> vs <code>params</code> <a class="header-anchor" href="#vue-路由-query-vs-params" aria-label="Permalink to &quot;Vue 路由：\`query\` vs \`params\`&quot;">​</a></h2><ol><li><p><strong>URL 表现形式</strong></p><ul><li>query：参数以 <code>?key=value</code> 形式附加在 URL 后面，如 <code>/search?keyword=vue&amp;page=1</code></li><li>params：参数嵌入在 URL 路径中，如 <code>/user/123</code></li></ul></li><li><p><strong>路由配置</strong></p><ul><li>query：无需在路由配置中预定义，随时可加任意键值对</li><li>params：必须在路由配置中声明动态段，如 <code>path: &#39;/user/:id&#39;</code></li></ul></li><li><p><strong>跳转方式</strong></p><ul><li>query：支持 <code>path</code> 或 <code>name</code> 跳转<div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.$router.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ path: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/search&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, query: { keyword: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } });</span></span></code></pre></div></li><li>params：<strong>必须使用 <code>name</code> 跳转</strong>，用 <code>path</code> 会导致参数丢失<div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.$router.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">push</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;User&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, params: { id: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } });</span></span></code></pre></div></li></ul></li><li><p><strong>取值方式</strong></p><ul><li>query：<code>this.$route.query.keyword</code></li><li>params：<code>this.$route.params.id</code></li></ul></li><li><p><strong>刷新行为</strong></p><ul><li>query：参数保留在 URL 中，刷新后不丢失</li><li>params：如果路由 path 中定义了动态段（如 <code>/user/:id</code>），刷新后参数仍在 URL 路径中，不会丢失；但如果 params 是隐式传递（未在路径中定义），刷新后会丢失</li></ul></li></ol><h2 id="浅谈vue-2-中的-computed-实现" tabindex="-1">浅谈Vue 2 中的 <code>computed</code> 实现 <a class="header-anchor" href="#浅谈vue-2-中的-computed-实现" aria-label="Permalink to &quot;浅谈Vue 2 中的 \`computed\` 实现&quot;">​</a></h2><p>Vue 2 中 <code>computed</code> 的实现，本质上是<strong>基于响应式系统（Dep/Watcher）+ 惰性求值（lazy）+ 脏标记（dirty）缓存</strong>三者协作的结果。</p><div class="info custom-block"><p class="custom-block-title">整体流程图</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始化</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 创建 computed Watcher（lazy: true, dirty: true）</span></span>
<span class="line"><span>  ├─ 不执行 getter，不收集依赖</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>首次访问 computed</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ dirty === true → 执行 evaluate()</span></span>
<span class="line"><span>  │   ├─ 调用 getter → 触发依赖数据的 get → 收集依赖</span></span>
<span class="line"><span>  │   ├─ 缓存结果到 watcher.value</span></span>
<span class="line"><span>  │   └─ dirty = false</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>再次访问（依赖未变）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ dirty === false → 直接返回 watcher.value（命中缓存）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>依赖数据变化</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 触发 computed Watcher 的 update()</span></span>
<span class="line"><span>  ├─ dirty = true（仅标记，不计算）</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>下次访问</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  └─ dirty === true → 重新 evaluate() → 重新收集依赖 → 更新缓存</span></span></code></pre></div><ul><li>每个 computed 属性对应一个 <strong>computed Watcher</strong>，存储在 <code>vm._computedWatchers</code> 中</li><li>创建时传入 <code>{ lazy: true }</code>，表示<strong>惰性求值</strong>——初始化时不执行 getter，不会立即计算</li></ul></div>`,6)])])}const k=a(p,[["render",t]]);export{u as __pageData,k as default};
